+
+import org.w3c.dom.Document;
+
+import org.xml.sax.ErrorHandler;
+import org.xml.sax.SAXException;
+import org.xml.sax.SAXParseException;
+
+import javax.xml.XMLConstants;
+import javax.xml.parsers.DocumentBuilder;
+import javax.xml.parsers.DocumentBuilderFactory;
+import javax.xml.transform.stream.StreamSource;
+import javax.xml.validation.Schema;
+import javax.xml.validation.SchemaFactory;
+import javax.xml.validation.Validator;
+import java.io.File;
+
+public class ConfigService {
+
+    /**
+     * Validates and loads an XML configuration file.
+     *
+     * @param configPath path to the XML configuration file
+     * @return the parsed Document object
+     * @throws IllegalArgumentException if configPath is null, empty, or the file does not exist
+     * @throws RuntimeException         if validation or parsing fails
+     */
+    public Document loadConfig(String configPath) {
+        if (configPath == null || configPath.trim().isEmpty()) {
+            throw new IllegalArgumentException("configPath must not be null or empty");
+        }
+
+        File configFile = new File(configPath);
+        if (!configFile.exists()) {
+            throw new IllegalArgumentException("Configuration file not found: " + configPath);
+        }
+
+        try {
+            // Step 1: Validate XML well-formedness using SchemaFactory and Validator
+            SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
+            Schema schema = schemaFactory.newSchema();
+            Validator validator = schema.newValidator();
+
+            // Only treat fatal (well-formedness) errors as errors;
+            // schema-compliance errors (e.g. missing element declarations) are ignored
+            // since we are only verifying well-formedness.
+            validator.setErrorHandler(new ErrorHandler() {
+                @Override
+                public void warning(SAXParseException e) {
+                    // ignore warnings
+                }
+
+                @Override
+                public void error(SAXParseException e) {
+                    // schema compliance errors are not well-formedness issues — ignore
+                }
+
+                @Override
+                public void fatalError(SAXParseException e) throws SAXException {
+                    throw e;
+                }
+            });
+
+            validator.validate(new StreamSource(configFile));
+
+            // Step 2: Parse the validated XML into a DOM Document
+            DocumentBuilderFactory docFactory = DocumentBuilderFactory.newInstance();
+            DocumentBuilder docBuilder = docFactory.newDocumentBuilder();
+            return docBuilder.parse(configFile);
+        } catch (Exception e) {
+            throw new RuntimeException("Failed to load configuration: " + e.getMessage(), e);
+        }
+    }
